start=time.monotonic()
with(work/'sent.tar').open('rb')as i,(work/'returned.tar').open('wb')as o,(work/'ssh.log').open('wb')as e:p=subprocess.run(['ssh','-o','BatchMode=yes','coderos-4080',remote],stdin=i,stdout=o,stderr=e,timeout=240)
