with tarfile.open(work/'returned.tar')as t:
 for m in t.getmembers():assert m.isfile()and m.name in['status.txt','native.log','probe','observations.rgba32f'];(work/m.name).write_bytes(t.extractfile(m).read())
status=int((work/'status.txt').read_text());assert status==0,(work/'native.log').read_text();record=json.loads(next(x for x in(work/'native.log').read_text().splitlines()if x.startswith('{')));record['cases_sha256']=hashlib.sha256((root/'aethyr/tests/render-filter-format-cases.json').read_bytes()).hexdigest();record['elapsed_seconds']=time.monotonic()-start;record['source_sha256']=before;record['source_fence']={p:hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in before.items()};record['executable_sha256']=hashlib.sha256((work/'probe').read_bytes()).hexdigest();record['shader_source_sha256']=hashlib.sha256((root/'aethyr/tests/render-filter-format-probe.coax').read_bytes()).hexdigest();record['compiler_sha256']=hashlib.sha256((root/'coax/bin/coax').read_bytes()).hexdigest();(work/'qualification.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record))
